import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

contracts_root = write_project('native_import_contracts', '''
    use core.fs;
    use core.proc;
    use core.storage;
    use core.thread;
    fn worker() -> i32 {
        return 1
    }
    fn main() -> i32 {
        let group = task.group_begin()
        discard task.group_spawn(group, worker)
        discard task.group_join_all(group)
        let cancel_group = task.group_begin()
        discard task.group_cancel(cancel_group)
        let argv = proc.argv_new()
        let env_map = proc.env_new()
        let handle = proc.spawn_cmd("echo", argv, env_map, "")
        discard proc.poll(handle)
        discard proc.wait(handle, 1000)
        discard proc.close(handle)
        discard fs.atomic_write("/tmp/fzy-native-contracts.txt", "hello")
        discard storage.atomic_append("/tmp/fzy-native-contracts.log", "entry")
        return 0
    }
''')
proc = subprocess.run([str(fz), 'build', str(contracts_root), '--json'], cwd=str(repo), capture_output=True, text=True)
payload = json.loads(proc.stdout.strip())
assert proc.returncode == 0, (proc.returncode, payload, proc.stderr)
runtime_contracts = json.loads((contracts_root / '.fz' / 'native-runtime-contracts.json').read_text())
contracts_by_callee = {item['callee']: item for item in runtime_contracts}
for callee, arg_ownership, blocking in [
    ('proc.close', 'consume_arg0', 'nonblocking'),
    ('proc.wait', 'borrow_handle_timeout', 'may_block'),
    ('proc.poll', 'borrow_handle', 'nonblocking'),
    ('task.group_join_all', 'consume_arg0', 'nonblocking'),
    ('task.group_cancel', 'consume_arg0', 'nonblocking'),
    ('fs.atomic_write', 'borrow_path_bytes', 'may_block'),
    ('storage.atomic_append', 'borrow_target_bytes', 'may_block'),
]:
    item = contracts_by_callee.get(callee)
    assert item is not None, (callee, runtime_contracts)
    assert item['argOwnership'] == arg_ownership, (callee, item)
    assert item['blockingBehavior'] == blocking, (callee, item)

atomic_root = write_project('native_import_runtime', '''
    use core.fs;
    use core.proc;
    use core.storage;

    fn main() -> i32 {
        let env_map = proc.env_new()
        let argv = proc.argv_new()
        discard proc.argv_push(argv, "-lc")
        discard proc.argv_push(argv, "sleep 0.2; printf ready")
        let handle = proc.spawn_cmd("/bin/sh", argv, env_map, "")
        let first = proc.poll(handle)
        let waited = proc.wait(handle, 1000)
        let second = proc.poll(handle)
        let exit_code = proc.exit_code(handle)
        let stdout = proc.stdout(handle)
        discard proc.close(handle)
        discard fs.atomic_write("__ATOMIC__", "alpha")
        discard storage.atomic_append("__APPEND__", "first")
        discard storage.atomic_append("__APPEND__", "second")
        let state = fs.read_file("__ATOMIC__")
        let audit = fs.read_file("__APPEND__")
        if first == 0 && waited == 0 && second == 1 && exit_code == 0 && stdout == "ready" && state == "alpha" && audit == "first\nsecond\n" {
            return 0
        }
        return 13
    }
''')
atomic_path = atomic_root / 'state.txt'
append_path = atomic_root / 'audit.log'
source = (atomic_root / 'src/main.fzy').read_text()
source = source.replace('__ATOMIC__', atomic_path.as_posix()).replace('__APPEND__', append_path.as_posix())
(atomic_root / 'src/main.fzy').write_text(source)
run_proc = subprocess.run([str(fz), 'run', str(atomic_root), '--proc-backend', 'host', '--fs-backend', 'host', '--http-backend', 'host', '--json'], cwd=str(repo), capture_output=True, text=True)
run_payload = json.loads(run_proc.stdout.strip())
assert run_proc.returncode == 0, (run_proc.returncode, run_payload, run_proc.stderr)
assert run_payload['status'] == 'pass', run_payload
assert atomic_path.read_text() == 'alpha', atomic_path.read_text()
assert append_path.read_text() == 'first\nsecond\n', append_path.read_text()
print('compiler-native-import-contracts-ok')

